-- Lot éditorial Spoontrotter généré par scripts/recipe-batches/build.mjs : 26 recettes, 12 nouveaux lieux.
-- Recettes rédigées pour l'application (adaptations éditoriales) à partir des compositions traditionnelles documentées.
-- Données source : data/recipe-batches/. Photos : Wikimedia Commons, vérifiées une à une (auteur et licence conservés).
-- Chargeur temporaire (pg_temp : disparaît à la fin de la session, jamais exposé à l'API).
create or replace function pg_temp.spoontrotter_import(batch jsonb) returns integer
language plpgsql as $fn$
declare
  r jsonb;
  p jsonb;
  ph jsonb;
  rid uuid;
  country_place uuid;
  place uuid;
  place_name text;
  region_text text;
  source_name constant text := 'Spoontrotter — adaptation éditoriale';
  author constant uuid := 'ac515660-4852-4ebd-8cb5-3348d60e06e9';
  total integer := 0;
begin
  for r in select value from jsonb_array_elements(batch) loop
    select id into country_place from public.culinary_places
      where country_code = r->>'country' and place_type = 'country' order by created_at limit 1;
    if country_place is null then
      raise exception 'Pays absent de l''atlas : %', r->>'country';
    end if;

    p := r->'place';
    if jsonb_typeof(p) = 'object' then
      insert into public.culinary_places (slug, name, country_code, place_type, parent_id, latitude, longitude, default_zoom, summary, is_active)
      values (p->>'slug', p->>'name', r->>'country', p->>'type', country_place, (p->>'lat')::float8, (p->>'lng')::float8,
              coalesce((p->>'zoom')::float8, case when p->>'type' = 'region' then 7 else 9 end), p->>'summary', true)
      on conflict (slug) do nothing;
      select id, name into place, place_name from public.culinary_places where slug = p->>'slug';
    elsif jsonb_typeof(p) = 'string' then
      select id, name into place, place_name from public.culinary_places where slug = p #>> '{}';
      if place is null then
        raise exception 'Lieu absent de l''atlas : %', p #>> '{}';
      end if;
    else
      place := country_place;
      place_name := null;
    end if;

    region_text := coalesce(r->>'region', place_name);
    rid := md5('spoontrotter:recipe:' || (r->>'slug'))::uuid;
    ph := r->'photo';

    insert into public.recipes (id, author_id, title, original_title, slug, description, excerpt, source_language, country_code, region,
      category, authenticity, status, difficulty, prep_minutes, cook_minutes, servings, published_at, primary_place_id,
      is_editorial, is_borderless, source_name, source_url, source_notes)
    values (rid, author, r->>'title', r->>'original', r->>'slug', r->>'desc', r->>'desc', 'fr', r->>'country', region_text,
      r->>'cat', coalesce(r->>'auth', 'adapted')::public.recipe_authenticity, 'published', (r->>'diff')::public.recipe_difficulty,
      (r->>'prep')::int, (r->>'cook')::int, (r->>'serv')::numeric, now(), place,
      true, false, source_name, ph->>'page',
      'Recette éditoriale rédigée pour l’application à partir de la composition traditionnelle documentée du plat.')
    on conflict (id) do update set title = excluded.title, original_title = excluded.original_title, description = excluded.description,
      excerpt = excluded.excerpt, country_code = excluded.country_code, region = excluded.region, category = excluded.category,
      difficulty = excluded.difficulty, prep_minutes = excluded.prep_minutes, cook_minutes = excluded.cook_minutes,
      servings = excluded.servings, primary_place_id = excluded.primary_place_id, source_url = excluded.source_url, updated_at = now();

    delete from public.recipe_ingredients where recipe_id = rid;
    insert into public.recipe_ingredients (recipe_id, position, name, quantity, unit, note)
    select rid, (t.o - 1)::int, t.e->>0, (t.e->>1)::numeric, t.e->>2, t.e->>3
    from jsonb_array_elements(r->'ing') with ordinality as t(e, o);

    delete from public.recipe_steps where recipe_id = rid;
    insert into public.recipe_steps (recipe_id, position, instruction)
    select rid, (t.o - 1)::int, t.s from jsonb_array_elements_text(r->'steps') with ordinality as t(s, o);

    delete from public.recipe_title_translations where recipe_id = rid;
    insert into public.recipe_title_translations (recipe_id, language_code, title, model) values
      (rid, 'fr', r->>'title', 'editorial-seed'),
      (rid, 'en', r->>'en', 'editorial-reviewed'),
      (rid, 'es', r->>'es', 'editorial-reviewed');

    delete from public.recipe_locations where recipe_id = rid;
    insert into public.recipe_locations (recipe_id, place_id, relation, is_primary) values (rid, place, 'origin', true);
    if place <> country_place then
      insert into public.recipe_locations (recipe_id, place_id, relation, is_primary) values (rid, country_place, 'origin', false);
    end if;

    delete from public.place_specialties where recipe_id = rid;
    insert into public.place_specialties (place_id, recipe_id, name, description, origin_note, is_signature, sort_order, source_name, source_url)
    values (place, rid, r->>'original', r->>'desc', coalesce(region_text, (select name from public.culinary_places where id = country_place)),
            place <> country_place, 10, source_name, ph->>'page');

    delete from public.recipe_images where recipe_id = rid and source_type = 'external_licensed';
    if jsonb_typeof(ph) = 'object' then
      insert into public.recipe_images (recipe_id, source_type, status, external_url, alt_text, source_name, source_page_url,
        photographer_name, license_name, license_url, attribution_text, is_primary, is_representative, moderation_notes)
      values (rid, 'external_licensed', 'ready', ph->>'url', r->>'title', coalesce(ph->>'source', 'Wikimedia Commons'), ph->>'page',
        nullif(ph->>'author', ''), ph->>'license', nullif(ph->>'licenseUrl', ''),
        'Photo : ' || coalesce(nullif(ph->>'author', ''), 'auteur inconnu') || ' · ' || (ph->>'license') || ' · ' || coalesce(ph->>'source', 'Wikimedia Commons'),
        true, true, 'Photo libre vérifiée à l’œil : le fichier représente ce plat.');
    end if;

    total := total + 1;
  end loop;
  return total;
end;
$fn$;
select pg_temp.spoontrotter_import($batch$[{"slug":"boulets-a-la-liegeoise","country":"BE","original":"Boulets à la liégeoise","title":"Boulets à la liégeoise (boulettes sauce lapin au sirop de Liège)","en":"Liège meatballs in sirop sauce","es":"Albóndigas a la lieja","desc":"Grosses boulettes de porc et bœuf nappées d'une sauce aigre-douce au sirop de Liège et aux oignons, servies avec des frites.","cat":"Plat principal","diff":"medium","prep":25,"cook":60,"serv":4,"place":"be-liege","ing":[["Haché porc et bœuf",800,"g",null],["Pain rassis trempé dans le lait",2,"tranches",null],["Œufs",2,null,null],["Oignons",4,null,"émincés"],["Sirop de Liège",3,"c. à soupe",null],["Vinaigre de vin",2,"c. à soupe",null],["Bouillon de bœuf",500,"ml",null],["Thym et laurier",1,"bouquet",null],["Beurre",50,"g",null],["Raisins secs",50,"g","facultatif"]],"steps":["Mélanger le haché, le pain essoré, les œufs, sel, poivre et muscade.","Façonner 8 grosses boulettes.","Les dorer au beurre dans une cocotte puis les réserver.","Faire fondre les oignons dans la même cocotte 15 minutes.","Ajouter le sirop de Liège, le vinaigre, le bouillon, le thym, le laurier et les raisins.","Remettre les boulettes et mijoter 40 minutes à couvert.","Rectifier l'assaisonnement et servir avec des frites."],"photo":{"file":"File:Boulets à la liégeoise 1.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/05/Boulets_%C3%A0_la_li%C3%A9geoise_1.jpg/1280px-Boulets_%C3%A0_la_li%C3%A9geoise_1.jpg","page":"https://commons.wikimedia.org/wiki/File:Boulets_%C3%A0_la_li%C3%A9geoise_1.jpg","author":"Marianne Casamance","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","source":"Wikimedia Commons"}},{"slug":"tarte-au-riz-verviers","country":"BE","original":"Tarte au riz","title":"Tarte au riz verviétoise","en":"Verviers rice tart","es":"Tarta de arroz de Verviers","desc":"Pâte levée garnie de riz cuit lentement dans du lait vanillé et des œufs, spécialité des pâtisseries de Verviers et de la région liégeoise.","cat":"Dessert","diff":"medium","prep":40,"cook":90,"serv":8,"place":{"slug":"be-verviers","name":"Verviers","type":"city","lat":50.5891,"lng":5.8622,"summary":"Ville lainière de la province de Liège, berceau de la tarte au riz."},"ing":[["Farine",250,"g",null],["Levure fraîche",10,"g",null],["Lait (pâte)",100,"ml",null],["Beurre",60,"g",null],["Riz rond",200,"g",null],["Lait (garniture)",1,"l",null],["Sucre",150,"g",null],["Œufs",3,null,null],["Gousse de vanille",1,null,null]],"steps":["Cuire le riz dans le lait vanillé à feu doux 45 minutes en remuant souvent, puis ajouter le sucre et laisser tiédir.","Pétrir farine, levure délayée dans le lait tiède, beurre, une pincée de sel et 1 œuf; laisser lever 1 heure.","Incorporer les 2 autres œufs au riz tiède.","Abaisser la pâte finement et foncer un moule beurré.","Verser la garniture.","Cuire 35 à 40 minutes à 180 °C jusqu'à ce que le dessus soit doré.","Servir froid."],"photo":{"file":"File:Tarte au riz.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/9/9c/Tarte_au_riz.jpg","page":"https://commons.wikimedia.org/wiki/File:Tarte_au_riz.jpg","author":"No machine-readable author provided. Frinck51~commonswiki assumed (based on copyright claims).","license":"CC BY-SA 3.0","licenseUrl":"http://creativecommons.org/licenses/by-sa/3.0/","source":"Wikimedia Commons"}},{"slug":"speculoos","country":"BE","original":"Speculoos","title":"Speculoos belges aux épices","en":"Belgian speculoos biscuits","es":"Speculoos belgas","desc":"Biscuits secs à la cassonade et aux épices (cannelle, girofle, muscade), traditionnellement moulés pour la Saint-Nicolas en Flandre.","cat":"Biscuits","diff":"easy","prep":20,"cook":15,"serv":30,"place":"be-flanders","ing":[["Farine",250,"g",null],["Cassonade brune",150,"g",null],["Beurre mou",125,"g",null],["Œuf",1,null,null],["Cannelle",2,"c. à café",null],["Épices à speculoos",1,"c. à café","girofle, muscade, gingembre, cardamome"],["Bicarbonate",0.5,"c. à café",null]],"steps":["Crémer le beurre et la cassonade.","Ajouter l'œuf puis la farine, les épices, le bicarbonate et une pincée de sel.","Former une boule, filmer et réfrigérer une nuit.","Abaisser à 4 mm et découper ou mouler les biscuits.","Cuire 12 à 15 minutes à 180 °C.","Laisser refroidir sur grille: ils durcissent en refroidissant."],"photo":{"file":"File:Speculoos.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/23/Speculoos.jpg/1280px-Speculoos.jpg","page":"https://commons.wikimedia.org/wiki/File:Speculoos.jpg","author":"Oreo Priest","license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","source":"Wikimedia Commons"}},{"slug":"kibbeling","country":"NL","original":"Kibbeling","title":"Kibbeling (bouchées de poisson frit, sauce ravigote)","en":"Kibbeling (Dutch fried fish bites)","es":"Kibbeling","desc":"Morceaux de cabillaud enrobés d'une pâte épicée et frits, servis avec une sauce à l'ail ou une ravigote, sur les marchés néerlandais.","cat":"Cuisine de rue","diff":"easy","prep":15,"cook":10,"serv":4,"place":{"slug":"nl-scheveningen","name":"Scheveningen","type":"locality","lat":52.1083,"lng":4.2733,"summary":"Port de pêche de La Haye où l'on fête chaque juin l'arrivée du premier hareng nouveau."},"ing":[["Filets de cabillaud ou merlu",600,"g",null],["Farine",120,"g",null],["Lait ou bière",150,"ml",null],["Œuf",1,null,null],["Épices à poisson",2,"c. à café","paprika, ail, poivre"],["Huile de friture",1,"l",null],["Mayonnaise",150,"g",null],["Ail",1,"gousse",null]],"steps":["Couper le poisson en bouchées.","Mélanger farine, épices, sel, œuf et lait en pâte lisse.","Enrober les morceaux de poisson.","Frire à 180 °C 3 à 4 minutes jusqu'à ce qu'ils soient dorés.","Mélanger la mayonnaise avec l'ail râpé et un peu d'aneth.","Servir aussitôt avec la sauce et du citron."],"photo":{"file":"File:Kibbeling 001.JPG","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/a3/Kibbeling_001.JPG/1280px-Kibbeling_001.JPG","page":"https://commons.wikimedia.org/wiki/File:Kibbeling_001.JPG","author":"Janericloebe","license":"Public domain","licenseUrl":null,"source":"Wikimedia Commons"}},{"slug":"limburgse-vlaai","country":"NL","original":"Limburgse vlaai","title":"Vlaai du Limbourg aux cerises","en":"Limburg vlaai (cherry tart)","es":"Vlaai de Limburgo","desc":"Tarte à pâte levée garnie de cerises et couverte d'un treillis, emblème des fêtes de la province néerlandaise du Limbourg.","cat":"Dessert","diff":"medium","prep":40,"cook":30,"serv":8,"place":{"slug":"nl-limburg","name":"Limbourg néerlandais","type":"region","lat":50.95,"lng":5.85,"summary":"Province du sud des Pays-Bas autour de Maastricht, terre de la vlaai."},"ing":[["Farine",250,"g",null],["Levure fraîche",15,"g",null],["Lait tiède",100,"ml",null],["Beurre",40,"g",null],["Sucre",40,"g",null],["Œuf",1,null,null],["Griottes dénoyautées",500,"g",null],["Fécule",2,"c. à soupe",null]],"steps":["Pétrir farine, levure délayée, lait, beurre, sucre, sel et œuf; laisser lever 45 minutes.","Cuire les cerises avec 60 g de sucre puis lier avec la fécule délayée; laisser refroidir.","Abaisser 2/3 de la pâte et foncer un moule à vlaai beurré.","Garnir de cerises.","Découper le reste de pâte en lanières et former un treillis.","Laisser lever 15 minutes puis cuire 25 minutes à 220 °C."],"photo":{"file":"File:Kirsch-Vlario.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/a0/Kirsch-Vlario.jpg/1280px-Kirsch-Vlario.jpg","page":"https://commons.wikimedia.org/wiki/File:Kirsch-Vlario.jpg","author":"No machine-readable author provided. Vlario assumed (based on copyright claims).","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","source":"Wikimedia Commons"}},{"slug":"chlebicky-praha","country":"CZ","original":"Chlebíčky","title":"Chlebíčky pragois (tartines garnies)","en":"Prague chlebíčky (open sandwiches)","es":"Chlebíčky de Praga","desc":"Tranches de baguette garnies de salade de pommes de terre, jambon, œuf, cornichon et fromage, en-cas des fêtes et des traiteurs pragois.","cat":"Entrée","diff":"easy","prep":30,"cook":0,"serv":6,"place":"cz-prague","ing":[["Baguette (veka)",1,null,"en tranches biaises"],["Pommes de terre cuites",300,"g",null],["Mayonnaise",150,"g",null],["Petits pois et carottes cuits",100,"g",null],["Jambon",150,"g",null],["Œufs durs",3,null,null],["Edam",100,"g",null],["Cornichons",4,null,null],["Poivron rouge",1,null,null]],"steps":["Couper pommes de terre, carottes et cornichons en petits dés.","Lier avec la mayonnaise et les pois; saler, poivrer.","Tartiner les tranches de pain de cette salade.","Disposer jambon roulé, rondelles d'œuf et fromage.","Décorer de cornichon et de poivron.","Réfrigérer 30 minutes avant de servir."],"photo":{"file":"File:Chlebicky.JPG","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/bf/Chlebicky.JPG/1280px-Chlebicky.JPG","page":"https://commons.wikimedia.org/wiki/File:Chlebicky.JPG","author":"KaHe","license":"CC BY-SA 3.0","licenseUrl":"http://creativecommons.org/licenses/by-sa/3.0/","source":"Wikimedia Commons"}},{"slug":"utopenci","country":"CZ","original":"Utopenci","title":"Utopenci (saucisses marinées au vinaigre)","en":"Utopenci (Czech pickled sausages)","es":"Utopenci","desc":"« Les noyés » : saucisses grasses marinées dans un vinaigre aux oignons et au piment, servies avec du pain dans les brasseries tchèques.","cat":"Entrée","diff":"easy","prep":20,"cook":5,"serv":6,"place":"cz-prague","ing":[["Saucisses špekáčky",6,null,null],["Oignons",3,null,"en rondelles"],["Vinaigre",250,"ml",null],["Eau",500,"ml",null],["Sucre",2,"c. à soupe",null],["Grains de poivre et piment de la Jamaïque",1,"c. à soupe",null],["Feuilles de laurier",3,null,null],["Piment frais",1,null,null]],"steps":["Porter eau, vinaigre, sucre, sel et épices à ébullition puis laisser refroidir.","Peler les saucisses et les fendre en long sans les séparer.","Glisser des rondelles d'oignon dans les entailles.","Les tasser dans un bocal en alternant oignon et piment.","Couvrir de marinade.","Laisser mariner au frais au moins 5 jours.","Servir avec du pain et de la bière."],"photo":{"file":"File:Utopenci 2.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/f/f5/Utopenci_2.jpg","page":"https://commons.wikimedia.org/wiki/File:Utopenci_2.jpg","author":"Karelj","license":"CC BY-SA 3.0","licenseUrl":"http://creativecommons.org/licenses/by-sa/3.0/","source":"Wikimedia Commons"}},{"slug":"soparnik","country":"HR","original":"Soparnik","title":"Soparnik de Poljica (tourte aux blettes)","en":"Soparnik (Swiss chard pie)","es":"Soparnik","desc":"Fine tourte de pâte sans levain farcie de blettes, d'oignon et de persil, cuite sous la cendre puis arrosée d'huile d'olive à l'ail.","cat":"Plat principal","diff":"medium","prep":40,"cook":25,"serv":6,"place":{"slug":"hr-poljica","name":"Poljica","type":"locality","lat":43.45,"lng":16.75,"summary":"Région de villages entre Split et Omiš, gardienne de la tradition du soparnik."},"ing":[["Farine",500,"g",null],["Eau tiède",280,"ml",null],["Huile d'olive",6,"c. à soupe",null],["Blettes (feuilles)",1,"kg",null],["Oignon rouge",1,null,null],["Persil",1,"bouquet",null],["Ail",4,"gousses",null]],"steps":["Pétrir farine, eau, 2 c. à soupe d'huile et sel; laisser reposer 30 minutes.","Hacher finement les feuilles de blette, l'oignon et le persil; assaisonner d'huile et de sel.","Abaisser la pâte en deux grands disques très fins.","Étaler la farce sur un disque, couvrir de l'autre et souder les bords.","Cuire 20 à 25 minutes à 250 °C (ou sur la sole d'un four à bois).","Badigeonner aussitôt d'huile d'olive à l'ail haché et découper en losanges."],"photo":{"file":"File:Whole-grain soparnik slice.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/4/4c/Whole-grain_soparnik_slice.jpg","page":"https://commons.wikimedia.org/wiki/File:Whole-grain_soparnik_slice.jpg","author":"Gaga","license":"CC BY 3.0","licenseUrl":"https://creativecommons.org/licenses/by/3.0","source":"Wikimedia Commons"}},{"slug":"rozata-dubrovnik","country":"HR","original":"Rožata","title":"Rožata de Dubrovnik (crème caramel à la rose)","en":"Dubrovnik rožata (rose custard)","es":"Rožata de Dubrovnik","desc":"Crème renversée au caramel parfumée à la liqueur de rose (rozalin) et au zeste de citron, dessert emblématique de Dubrovnik.","cat":"Dessert","diff":"medium","prep":20,"cook":50,"serv":6,"place":{"slug":"hr-dubrovnik","name":"Dubrovnik","type":"city","lat":42.6507,"lng":18.0944,"summary":"Cité fortifiée de l'Adriatique, réputée pour la rožata."},"ing":[["Lait entier",1,"l",null],["Œufs",6,null,null],["Sucre (crème)",120,"g",null],["Sucre (caramel)",150,"g",null],["Liqueur de rose ou eau de rose",2,"c. à soupe",null],["Zeste de citron",1,null,null],["Gousse de vanille",1,null,null]],"steps":["Chauffer le lait avec la vanille et le zeste puis laisser infuser.","Faire un caramel blond et en napper le fond d'un moule.","Fouetter les œufs avec le sucre sans faire mousser.","Verser le lait chaud filtré en mélangeant, ajouter la liqueur de rose.","Verser sur le caramel et cuire au bain-marie à 160 °C environ 50 minutes.","Refroidir puis réfrigérer une nuit et démouler."],"photo":{"file":"File:Rožata-zg.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/3/30/Ro%C5%BEata-zg.jpg","page":"https://commons.wikimedia.org/wiki/File:Ro%C5%BEata-zg.jpg","author":"Bonč","license":"Public domain","licenseUrl":null,"source":"Wikimedia Commons"}},{"slug":"sardinhas-assadas-lisboa","country":"PT","original":"Sardinhas assadas","title":"Sardines grillées de Lisbonne","en":"Lisbon grilled sardines","es":"Sardinas asadas de Lisboa","desc":"Sardines entières salées au gros sel et grillées sur la braise, servies sur une tranche de pain avec poivrons grillés, plat des fêtes de la Saint-Antoine.","cat":"Plat principal","diff":"easy","prep":10,"cook":10,"serv":4,"place":"pt-lisbon","ing":[["Sardines fraîches entières",12,null,null],["Gros sel",3,"c. à soupe",null],["Pain de campagne",4,"tranches",null],["Poivrons rouges",2,null,null],["Huile d'olive",3,"c. à soupe",null],["Pommes de terre bouillies",500,"g","facultatif"]],"steps":["Couvrir les sardines non vidées de gros sel 30 minutes.","Griller les poivrons sur la braise, les peler et les assaisonner d'huile.","Secouer l'excédent de sel des sardines.","Les griller 3 à 4 minutes de chaque côté sur une braise vive.","Servir chaque sardine posée sur une tranche de pain, avec les poivrons et des pommes de terre."],"photo":{"file":"File:Sardinhas assadas.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/e8/Sardinhas_assadas.jpg/1280px-Sardinhas_assadas.jpg","page":"https://commons.wikimedia.org/wiki/File:Sardinhas_assadas.jpg","author":"Duarte Briz","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"Wikimedia Commons"}},{"slug":"alheira-de-mirandela","country":"PT","original":"Alheira de Mirandela","title":"Alheira de Mirandela grillée, œuf et frites","en":"Alheira de Mirandela with egg and fries","es":"Alheira de Mirandela","desc":"Saucisse fumée de volaille et de pain du Trás-os-Montes, grillée et servie avec un œuf au plat, des frites et des grelos.","cat":"Plat principal","diff":"easy","prep":10,"cook":20,"serv":4,"place":{"slug":"pt-mirandela","name":"Mirandela","type":"city","lat":41.4868,"lng":-7.1817,"summary":"Ville du Trás-os-Montes dont l'alheira est protégée par une IGP."},"ing":[["Alheiras de Mirandela",4,null,null],["Œufs",4,null,null],["Pommes de terre",600,"g",null],["Grelos ou chou vert",300,"g",null],["Huile d'olive",4,"c. à soupe",null],["Ail",2,"gousses",null]],"steps":["Piquer légèrement les alheiras et les cuire au four ou à la poêle 15 minutes en les retournant.","Tailler et frire les pommes de terre.","Faire sauter les grelos blanchis à l'huile et à l'ail.","Cuire les œufs au plat.","Servir l'alheira avec l'œuf, les frites et les grelos."],"photo":{"file":"File:Alheira frita (fried sausage) served at restaurant in Lisbon, Portugal (55067809476).jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/55/Alheira_frita_%28fried_sausage%29_served_at_restaurant_in_Lisbon%2C_Portugal_%2855067809476%29.jpg/1280px-Alheira_frita_%28fried_sausage%29_served_at_restaurant_in_Lisbon%2C_Portugal_%2855067809476%29.jpg","page":"https://commons.wikimedia.org/wiki/File:Alheira_frita_(fried_sausage)_served_at_restaurant_in_Lisbon,_Portugal_(55067809476).jpg","author":"Philip Mallis from Melbourne","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"Wikimedia Commons"}},{"slug":"polvo-a-lagareiro","country":"PT","original":"Polvo à lagareiro","title":"Poulpe à la lagareiro (poulpe rôti à l'huile d'olive)","en":"Octopus à lagareiro","es":"Pulpo a la lagareiro","desc":"Poulpe poché puis rôti, arrosé généreusement d'huile d'olive à l'ail et servi avec des petites pommes de terre écrasées au poing (batatas a murro).","cat":"Plat principal","diff":"medium","prep":20,"cook":75,"serv":4,"place":"pt-minho","ing":[["Poulpe",1.5,"kg",null],["Petites pommes de terre",800,"g",null],["Huile d'olive",200,"ml",null],["Ail",8,"gousses",null],["Oignon",1,null,null],["Gros sel",2,"c. à soupe",null],["Persil",1,"bouquet",null]],"steps":["Cuire le poulpe avec l'oignon dans l'eau frémissante 45 à 60 minutes jusqu'à ce qu'il soit tendre.","Cuire les pommes de terre en robe au four sur du gros sel 40 minutes.","Les écraser d'un coup de poing.","Couper le poulpe en tentacules et le rôtir 10 minutes à 220 °C.","Chauffer l'huile avec l'ail en lamelles sans le colorer.","Arroser poulpe et pommes de terre d'huile chaude et parsemer de persil."],"photo":{"file":"File:Polvo à Lagareiro.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/2a/Polvo_%C3%A0_Lagareiro.jpg/1280px-Polvo_%C3%A0_Lagareiro.jpg","page":"https://commons.wikimedia.org/wiki/File:Polvo_%C3%A0_Lagareiro.jpg","author":"August Dominus","license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","source":"Wikimedia Commons"}},{"slug":"bolinhos-de-bacalhau","country":"PT","original":"Pastéis de bacalhau","title":"Pastéis (bolinhos) de bacalhau","en":"Portuguese salt cod fritters","es":"Buñuelos de bacalao portugueses","desc":"Quenelles de morue dessalée, de pommes de terre et de persil, frites jusqu'à être croustillantes, en-cas incontournable des tascas.","cat":"Entrée","diff":"medium","prep":40,"cook":20,"serv":24,"place":"pt-lisbon","ing":[["Morue dessalée",400,"g",null],["Pommes de terre farineuses",400,"g",null],["Œufs",3,null,null],["Oignon",1,null,"très finement haché"],["Persil",1,"bouquet",null],["Huile de friture",1,"l",null]],"steps":["Pocher la morue 10 minutes, l'égoutter et l'effilocher très finement.","Cuire les pommes de terre et les réduire en purée sèche.","Mélanger morue, purée, oignon, persil et œufs; poivrer et ajouter muscade.","Façonner des quenelles avec deux cuillères.","Frire à 175 °C 3 à 4 minutes jusqu'à ce qu'elles soient dorées.","Égoutter et servir tiède ou froid."],"photo":{"file":"File:Bolinho de bacalhau.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/8/8a/Bolinho_de_bacalhau.jpg","page":"https://commons.wikimedia.org/wiki/File:Bolinho_de_bacalhau.jpg","author":"GostinhoDeBrasil","license":"CC BY 3.0","licenseUrl":"https://creativecommons.org/licenses/by/3.0","source":"Wikimedia Commons"}},{"slug":"arroz-de-pato-braga","country":"PT","original":"Arroz de pato à moda de Braga","title":"Arroz de pato de Braga (riz au canard et chouriço)","en":"Braga-style duck rice","es":"Arroz de pato de Braga","desc":"Riz cuit dans le bouillon de canard, mêlé à la viande effilochée et gratiné au four sous des rondelles de chouriço.","cat":"Plat principal","diff":"medium","prep":30,"cook":120,"serv":6,"place":{"slug":"pt-braga","name":"Braga","type":"city","lat":41.5454,"lng":-8.4265,"summary":"Ville religieuse du Minho, réputée pour son arroz de pato."},"ing":[["Canard",1,null,"environ 2 kg"],["Riz",400,"g",null],["Chouriço",1,null,null],["Lard fumé",100,"g",null],["Oignon",1,null,null],["Carotte",1,null,null],["Vin blanc",150,"ml",null],["Citron",1,null,"zeste"]],"steps":["Cuire le canard 1 heure 30 dans l'eau avec oignon, carotte, lard, la moitié du chouriço et le vin.","Effilocher la viande; filtrer et dégraisser le bouillon.","Faire revenir le riz dans un peu de graisse de canard.","Le cuire dans 800 ml de bouillon 12 minutes.","Alterner riz et canard dans un plat, couvrir de rondelles de chouriço et de lard.","Gratiner 15 minutes à 200 °C."],"photo":{"file":"File:Arroz de Pato (4948416093).jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/71/Arroz_de_Pato_%284948416093%29.jpg/1280px-Arroz_de_Pato_%284948416093%29.jpg","page":"https://commons.wikimedia.org/wiki/File:Arroz_de_Pato_(4948416093).jpg","author":"ricardo from London","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0","source":"Wikimedia Commons"}},{"slug":"pastitsio","country":"GR","original":"Παστίτσιο (Pastitsio)","title":"Pastitsio grec (gratin de pâtes à la viande et béchamel)","en":"Greek pastitsio","es":"Pastitsio griego","desc":"Pâtes tubulaires, sauce à la viande parfumée à la cannelle et épaisse couche de béchamel, gratinées au four.","cat":"Plat principal","diff":"medium","prep":40,"cook":60,"serv":8,"place":{"slug":"gr-athens","name":"Athènes","type":"city","lat":37.9838,"lng":23.7275,"summary":"Capitale grecque, mezedopolia et tavernes de quartier."},"ing":[["Pâtes tubulaires (n°2)",500,"g",null],["Bœuf haché",700,"g",null],["Oignon",1,null,null],["Coulis de tomate",400,"g",null],["Vin rouge",100,"ml",null],["Cannelle",1,"c. à café",null],["Beurre",100,"g",null],["Farine",100,"g",null],["Lait",1,"l",null],["Œufs",2,null,null],["Kefalotyri ou parmesan",100,"g",null]],"steps":["Faire revenir l'oignon et le bœuf, mouiller au vin, ajouter tomate, cannelle, sel, poivre; mijoter 30 minutes.","Cuire les pâtes al dente et les mêler à un œuf et la moitié du fromage.","Préparer une béchamel avec beurre, farine et lait; hors du feu, ajouter un œuf et le reste du fromage.","Étaler les pâtes, puis la viande, puis la béchamel.","Cuire 45 minutes à 180 °C jusqu'à ce que ce soit doré.","Laisser reposer 30 minutes avant de couper."],"photo":{"file":"File:Pastitsio.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/21/Pastitsio.jpg/1280px-Pastitsio.jpg","page":"https://commons.wikimedia.org/wiki/File:Pastitsio.jpg","author":"Robert Kindermann","license":"CC BY-SA 2.5","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.5","source":"Wikimedia Commons"}},{"slug":"giouvetsi","country":"GR","original":"Γιουβέτσι (Giouvetsi)","title":"Giouvetsi (agneau et orzo au four)","en":"Giouvetsi (lamb and orzo bake)","es":"Giouvetsi de cordero","desc":"Agneau braisé à la tomate et à la cannelle puis cuit au four avec des pâtes kritharaki dans un plat en terre, servi avec du fromage râpé.","cat":"Plat principal","diff":"easy","prep":20,"cook":120,"serv":6,"place":{"slug":"gr-athens","name":"Athènes","type":"city","lat":37.9838,"lng":23.7275,"summary":"Capitale grecque, mezedopolia et tavernes de quartier."},"ing":[["Épaule d'agneau en morceaux",1.2,"kg",null],["Kritharaki (orzo)",400,"g",null],["Oignon",1,null,null],["Ail",3,"gousses",null],["Tomates concassées",400,"g",null],["Bâton de cannelle",1,null,null],["Vin rouge",150,"ml",null],["Huile d'olive",4,"c. à soupe",null],["Kefalotyri râpé",80,"g",null]],"steps":["Dorer l'agneau dans l'huile, ajouter oignon et ail.","Mouiller au vin, ajouter tomates, cannelle, sel et poivre.","Transférer dans un plat en terre, couvrir et cuire 1 heure 30 à 180 °C.","Ajouter l'orzo et 1 l d'eau bouillante, mélanger.","Cuire encore 30 minutes à découvert en remuant une fois.","Servir parsemé de fromage râpé."],"photo":{"file":"File:Giouvetsi.JPG","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/f9/Giouvetsi.JPG/1280px-Giouvetsi.JPG","page":"https://commons.wikimedia.org/wiki/File:Giouvetsi.JPG","author":"Robert Kindermann","license":"CC BY-SA 2.5","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.5","source":"Wikimedia Commons"}},{"slug":"tiropita","country":"GR","original":"Τυρόπιτα (Tiropita)","title":"Tiropita (feuilleté grec à la feta)","en":"Tiropita (Greek cheese pie)","es":"Tiropita griega","desc":"Tourte de pâte filo beurrée garnie de feta et d'œufs, vendue dans les boulangeries grecques au petit-déjeuner.","cat":"Entrée","diff":"easy","prep":25,"cook":45,"serv":8,"place":{"slug":"gr-athens","name":"Athènes","type":"city","lat":37.9838,"lng":23.7275,"summary":"Capitale grecque, mezedopolia et tavernes de quartier."},"ing":[["Feuilles de pâte filo",12,null,null],["Feta",400,"g",null],["Ricotta ou anthotyro",200,"g",null],["Œufs",3,null,null],["Lait",100,"ml",null],["Beurre fondu",120,"g",null],["Poivre",1,"pincée",null]],"steps":["Émietter la feta et la mélanger avec la ricotta, les œufs, le lait et le poivre.","Beurrer un moule et y superposer 6 feuilles de filo en beurrant chacune.","Étaler la garniture.","Couvrir des 6 feuilles restantes, beurrées une à une.","Prédécouper le dessus en carrés et asperger de quelques gouttes d'eau.","Cuire 45 minutes à 180 °C jusqu'à ce que ce soit doré."],"photo":{"file":"File:Tiropita Greek dish.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/8b/Tiropita_Greek_dish.jpg/1280px-Tiropita_Greek_dish.jpg","page":"https://commons.wikimedia.org/wiki/File:Tiropita_Greek_dish.jpg","author":"Tanya Bakogiannis","license":"CC BY 3.0","licenseUrl":"https://creativecommons.org/licenses/by/3.0","source":"Wikimedia Commons"}},{"slug":"koulouri-thessalonikis","country":"GR","original":"Κουλούρι Θεσσαλονίκης","title":"Koulouri de Thessalonique (couronne de pain au sésame)","en":"Thessaloniki koulouri (sesame bread ring)","es":"Koulouri de Salónica","desc":"Anneau de pain croustillant entièrement couvert de sésame, vendu à chaque coin de rue de Thessalonique au petit-déjeuner.","cat":"Pain","diff":"medium","prep":30,"cook":20,"serv":10,"place":"gr-thessaloniki","ing":[["Farine",500,"g",null],["Eau tiède",300,"ml",null],["Levure sèche",7,"g",null],["Sucre",1,"c. à soupe",null],["Huile d'olive",2,"c. à soupe",null],["Graines de sésame",150,"g",null],["Pekmez (mélasse de raisin) ou miel",3,"c. à soupe",null]],"steps":["Pétrir farine, eau, levure, sucre, sel et huile; laisser lever 1 heure.","Diviser en 10 pâtons et rouler des boudins de 50 cm.","Les fermer en anneaux.","Les tremper dans le pekmez allongé d'eau puis dans le sésame.","Laisser lever 30 minutes.","Cuire 18 à 20 minutes à 220 °C."],"photo":{"file":"File:Athens15 tango7174.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/6/6b/Athens15_tango7174.jpg","page":"https://commons.wikimedia.org/wiki/File:Athens15_tango7174.jpg","author":"Tango7174","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"Wikimedia Commons"}},{"slug":"horiatiki","country":"GR","original":"Χωριάτικη σαλάτα","title":"Horiatiki (salade grecque villageoise)","en":"Horiatiki (Greek village salad)","es":"Ensalada horiatiki","desc":"Tomates, concombre, oignon, poivron et olives de Kalamata, coiffés d'une tranche de feta à l'origan et d'huile d'olive, sans laitue.","cat":"Entrée","diff":"easy","prep":15,"cook":0,"serv":4,"place":"gr-crete","ing":[["Tomates mûres",4,null,null],["Concombre",1,null,null],["Oignon rouge",1,null,null],["Poivron vert",1,null,null],["Olives de Kalamata",100,"g",null],["Feta",200,"g","en tranche"],["Origan séché",1,"c. à café",null],["Huile d'olive",80,"ml",null],["Câpres",1,"c. à soupe","facultatif"]],"steps":["Couper les tomates en quartiers et le concombre en demi-rondelles.","Émincer l'oignon et le poivron.","Disposer les légumes et les olives dans un plat; saler légèrement.","Poser la feta entière dessus.","Parsemer d'origan et arroser d'huile d'olive.","Servir avec du pain pour saucer."],"photo":{"file":"File:Flickr - cyclonebill - Græsk salat.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/54/Flickr_-_cyclonebill_-_Gr%C3%A6sk_salat.jpg/1280px-Flickr_-_cyclonebill_-_Gr%C3%A6sk_salat.jpg","page":"https://commons.wikimedia.org/wiki/File:Flickr_-_cyclonebill_-_Gr%C3%A6sk_salat.jpg","author":"cyclonebill","license":"CC BY-SA 2.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.0","source":"Wikimedia Commons"}},{"slug":"apfelstrudel-wien","country":"AT","original":"Wiener Apfelstrudel","title":"Apfelstrudel viennois","en":"Viennese apple strudel","es":"Strudel de manzana vienés","desc":"Pâte étirée à la main jusqu'à être transparente, roulée sur des pommes, raisins, cannelle et chapelure au beurre, servie tiède dans les cafés viennois.","cat":"Dessert","diff":"hard","prep":60,"cook":40,"serv":8,"place":"at-vienna","ing":[["Farine",250,"g",null],["Eau tiède",125,"ml",null],["Huile",2,"c. à soupe",null],["Pommes acidulées",1.2,"kg",null],["Sucre",100,"g",null],["Cannelle",1,"c. à café",null],["Raisins secs",60,"g",null],["Chapelure",80,"g",null],["Beurre",120,"g",null],["Sucre glace",2,"c. à soupe",null]],"steps":["Pétrir farine, eau, huile et sel en pâte lisse; huiler et laisser reposer 1 heure.","Dorer la chapelure dans 50 g de beurre.","Émincer les pommes et les mélanger au sucre, à la cannelle et aux raisins.","Étirer la pâte sur un linge fariné jusqu'à ce qu'elle soit transparente.","La badigeonner de beurre fondu, parsemer de chapelure puis des pommes.","Rouler à l'aide du linge et poser sur une plaque.","Badigeonner de beurre et cuire 40 minutes à 190 °C; poudrer de sucre glace."],"photo":{"file":"File:Apfelstrudel mit Vanillesauce Mai 2012.JPG","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/0c/Apfelstrudel_mit_Vanillesauce_Mai_2012.JPG/1280px-Apfelstrudel_mit_Vanillesauce_Mai_2012.JPG","page":"https://commons.wikimedia.org/wiki/File:Apfelstrudel_mit_Vanillesauce_Mai_2012.JPG","author":"4028mdk09","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","source":"Wikimedia Commons"}},{"slug":"tafelspitz","country":"AT","original":"Tafelspitz","title":"Tafelspitz viennois (bœuf bouilli, raifort aux pommes)","en":"Viennese Tafelspitz","es":"Tafelspitz vienés","desc":"Pointe de culotte de bœuf mijotée dans un bouillon clair, servie avec le bouillon, des pommes de terre sautées, du raifort aux pommes et une sauce à la ciboulette.","cat":"Plat principal","diff":"medium","prep":20,"cook":180,"serv":6,"place":"at-vienna","ing":[["Pointe de culotte de bœuf",1.5,"kg",null],["Os à moelle",2,null,null],["Légumes racines (carotte, céleri, poireau)",500,"g",null],["Oignon",1,null,"brûlé à sec, coupé en deux"],["Grains de poivre",1,"c. à café",null],["Pommes",2,null,null],["Raifort râpé",3,"c. à soupe",null],["Ciboulette",1,"bouquet",null],["Pommes de terre",800,"g",null]],"steps":["Plonger la viande et les os dans l'eau bouillante, écumer.","Ajouter l'oignon brûlé, les légumes et le poivre; frémir 2 heures 30 à 3 heures.","Râper les pommes, les arroser de citron et mêler au raifort.","Préparer la sauce ciboulette avec crème, mie de pain et ciboulette.","Rissoler les pommes de terre cuites à l'oignon.","Servir d'abord le bouillon avec la moelle, puis la viande tranchée et ses accompagnements."],"photo":{"file":"File:110123 Plachutta 14.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/c4/110123_Plachutta_14.jpg/1280px-110123_Plachutta_14.jpg","page":"https://commons.wikimedia.org/wiki/File:110123_Plachutta_14.jpg","author":"weisserstier","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0","source":"Wikimedia Commons"}},{"slug":"kaerntner-kasnudeln","country":"AT","original":"Kärntner Kasnudeln","title":"Kasnudeln de Carinthie (raviolis au fromage blanc et menthe)","en":"Carinthian Kasnudeln","es":"Kasnudeln de Carintia","desc":"Grands raviolis fermés par un pli tressé (krendeln), farcis de fromage blanc, pommes de terre, menthe et cerfeuil, arrosés de beurre noisette.","cat":"Plat principal","diff":"hard","prep":60,"cook":15,"serv":4,"place":{"slug":"at-carinthie","name":"Carinthie","type":"region","lat":46.72,"lng":14.18,"summary":"Land du sud de l'Autriche, lacs alpins et Kasnudeln."},"ing":[["Farine",300,"g",null],["Œuf",1,null,null],["Eau tiède",100,"ml",null],["Fromage blanc égoutté (Topfen)",250,"g",null],["Pommes de terre cuites écrasées",250,"g",null],["Menthe et cerfeuil hachés",3,"c. à soupe",null],["Oignon",1,null,null],["Beurre",80,"g",null]],"steps":["Pétrir farine, œuf, eau, sel et un peu d'huile; laisser reposer 30 minutes.","Faire fondre l'oignon haché au beurre et le mêler au fromage, aux pommes de terre et aux herbes; saler.","Abaisser la pâte finement et découper des disques de 10 cm.","Poser une boule de farce, replier et fermer en pinçant le bord en tresse.","Cuire 12 à 15 minutes dans l'eau salée frémissante.","Égoutter et arroser de beurre noisette."],"photo":{"file":"File:Kärntner Nudel handgekrendelt 01.JPG","url":"https://upload.wikimedia.org/wikipedia/commons/d/dd/K%C3%A4rntner_Nudel_handgekrendelt_01.JPG","page":"https://commons.wikimedia.org/wiki/File:K%C3%A4rntner_Nudel_handgekrendelt_01.JPG","author":"Joadl","license":"CC BY-SA 3.0 at","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0/at/deed.en","source":"Wikimedia Commons"}},{"slug":"roed-poelse-koebenhavn","country":"DK","original":"Røde pølser","title":"Røde pølser (hot-dog rouge de Copenhague)","en":"Copenhagen røde pølser (red hot dog)","es":"Røde pølser de Copenhague","desc":"Saucisse rouge vif servie dans un petit pain avec ketchup, moutarde, rémoulade danoise, oignons crus et frits et cornichons, au pølsevogn.","cat":"Cuisine de rue","diff":"easy","prep":15,"cook":10,"serv":4,"place":"dk-copenhagen","ing":[["Saucisses røde pølser",4,null,null],["Petits pains à hot-dog",4,null,null],["Rémoulade danoise",4,"c. à soupe",null],["Moutarde douce danoise",4,"c. à soupe",null],["Ketchup",4,"c. à soupe",null],["Oignon cru haché",1,null,null],["Oignons frits croustillants",4,"c. à soupe",null],["Cornichons aigres-doux",8,"tranches",null]],"steps":["Pocher les saucisses 8 minutes dans l'eau frémissante.","Réchauffer les pains.","Placer une saucisse dans chaque pain.","Napper de ketchup, moutarde et rémoulade.","Garnir d'oignon cru, d'oignons frits et de cornichons.","Servir aussitôt, avec un chocolat au lait selon la tradition."],"photo":{"file":"File:Rød pølse og Cocio (pølsevogn).jpeg","url":"https://upload.wikimedia.org/wikipedia/commons/f/fd/R%C3%B8d_p%C3%B8lse_og_Cocio_%28p%C3%B8lsevogn%29.jpeg","page":"https://commons.wikimedia.org/wiki/File:R%C3%B8d_p%C3%B8lse_og_Cocio_(p%C3%B8lsevogn).jpeg","author":"Royal Export","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"Wikimedia Commons"}},{"slug":"flaeskesteg","country":"DK","original":"Flæskesteg","title":"Flæskesteg (rôti de porc à la couenne croustillante)","en":"Danish flæskesteg (crackling pork roast)","es":"Flæskesteg danés","desc":"Rôti de longe de porc dont la couenne incisée devient craquante, servi avec chou rouge, pommes de terre caramélisées et sauce brune, plat du réveillon danois.","cat":"Plat principal","diff":"medium","prep":20,"cook":110,"serv":6,"place":"dk-copenhagen","ing":[["Longe de porc avec couenne",1.5,"kg",null],["Gros sel",2,"c. à soupe",null],["Feuilles de laurier",4,null,null],["Chou rouge braisé",500,"g",null],["Petites pommes de terre cuites",800,"g",null],["Sucre",60,"g",null],["Beurre",30,"g",null],["Fond de cuisson et crème",300,"ml","pour la sauce"]],"steps":["Inciser la couenne en profondeur tous les centimètres.","Frotter de gros sel en le glissant dans les entailles, piquer de laurier.","Poser couenne vers le bas dans 2 cm d'eau et cuire 20 minutes à 200 °C.","Retourner et cuire 1 heure 15 à 180 °C, puis 10 minutes à 250 °C pour faire gonfler la couenne.","Caraméliser le sucre, ajouter le beurre et rouler les pommes de terre dedans.","Préparer la sauce avec le jus de cuisson et la crème; servir avec le chou rouge."],"photo":{"file":"File:Flæskesteg rødkål brunede kartofler.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/40/Fl%C3%A6skesteg_r%C3%B8dk%C3%A5l_brunede_kartofler.jpg/1280px-Fl%C3%A6skesteg_r%C3%B8dk%C3%A5l_brunede_kartofler.jpg","page":"https://commons.wikimedia.org/wiki/File:Fl%C3%A6skesteg_r%C3%B8dk%C3%A5l_brunede_kartofler.jpg","author":"Nillerdk","license":"CC BY 3.0","licenseUrl":"https://creativecommons.org/licenses/by/3.0","source":"Wikimedia Commons"}},{"slug":"kurtoskalacs","country":"HU","original":"Kürtőskalács","title":"Kürtőskalács (gâteau-cheminée au sucre et à la cannelle)","en":"Kürtőskalács (chimney cake)","es":"Kürtőskalács","desc":"Ruban de pâte levée enroulé sur un cylindre de bois, cuit à la braise jusqu'à caraméliser le sucre, puis roulé dans la cannelle ou les noix.","cat":"Dessert","diff":"medium","prep":30,"cook":25,"serv":6,"place":"hu-budapest","ing":[["Farine",500,"g",null],["Lait tiède",250,"ml",null],["Levure fraîche",20,"g",null],["Sucre",50,"g",null],["Jaunes d'œufs",2,null,null],["Beurre fondu",60,"g",null],["Sucre (enrobage)",150,"g",null],["Cannelle ou noix moulues",3,"c. à soupe",null]],"steps":["Pétrir farine, lait, levure, sucre, jaunes, beurre et sel; laisser lever 1 heure.","Abaisser à 5 mm et découper un long ruban de 1,5 cm de large.","L'enrouler en spirale serrée sur un rouleau de bois beurré et enveloppé d'aluminium.","Badigeonner de beurre et rouler dans le sucre.","Cuire en tournant au-dessus de la braise ou au four à 200 °C 20 à 25 minutes.","Rouler dans la cannelle ou les noix et démouler encore chaud."],"photo":{"file":"File:Baumstriezel.JPG","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/05/Baumstriezel.JPG/1280px-Baumstriezel.JPG","page":"https://commons.wikimedia.org/wiki/File:Baumstriezel.JPG","author":"L.Kenzel","license":"CC BY 3.0","licenseUrl":"https://creativecommons.org/licenses/by/3.0","source":"Wikimedia Commons"}},{"slug":"hortobagyi-palacsinta","country":"HU","original":"Hortobágyi palacsinta","title":"Crêpes de Hortobágy (farcies au veau, sauce paprika)","en":"Hortobágy pancakes","es":"Crepes de Hortobágy","desc":"Crêpes roulées en paquets autour d'un ragoût de veau au paprika haché, nappées de la sauce paprika à la crème aigre et gratinées.","cat":"Plat principal","diff":"medium","prep":40,"cook":60,"serv":4,"place":{"slug":"hu-hortobagy","name":"Hortobágy","type":"region","lat":47.58,"lng":21.15,"summary":"Grande plaine (puszta) de l'est hongrois, terre des bergers et des csárdák."},"ing":[["Farine",150,"g",null],["Lait",300,"ml",null],["Œufs",2,null,null],["Épaule de veau",500,"g",null],["Oignons",2,null,null],["Paprika doux",2,"c. à soupe",null],["Poivron",1,null,null],["Tomate",1,null,null],["Crème aigre",200,"g",null],["Saindoux ou huile",2,"c. à soupe",null]],"steps":["Faire fondre les oignons au saindoux, hors du feu ajouter le paprika.","Ajouter le veau en dés, le poivron, la tomate, sel et un peu d'eau; mijoter 1 heure (pörkölt).","Préparer 8 crêpes fines avec farine, lait, œufs et sel.","Retirer la viande, la hacher finement et la lier avec un peu de sauce.","Garnir les crêpes et les plier en paquets.","Mêler le reste de sauce à la crème aigre, napper et passer 10 minutes au four à 180 °C."],"photo":{"file":"File:Hortobagy palacsinta.JPG","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/97/Hortobagy_palacsinta.JPG/1280px-Hortobagy_palacsinta.JPG","page":"https://commons.wikimedia.org/wiki/File:Hortobagy_palacsinta.JPG","author":"Themightyquill","license":"CC BY 2.5","licenseUrl":"https://creativecommons.org/licenses/by/2.5","source":"Wikimedia Commons"}}]$batch$::jsonb);
